using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change #2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .HasJsonPropertyName("id")
                .ToJsonProperty("id");

            // Breaking change #3: EF 9 no longer supports indexes on Cosmos (they were silently ignored before, now they throw).
            // REMOVED: entity.HasIndex(b => b.Name);

            // Breaking change #4: Sync I/O now throws by default in EF 9 Cosmos provider.
            // See SyncJob.cs for the fix (switched to async).
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If async migration isn't possible everywhere, you can re-enable sync I/O:
        // optionsBuilder.UseCosmos(...).ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
    }
}
